import{sceneMapModel,actorColor,pathMovement}from'./scene-map-model.js';
export function mountSceneMap({host,api,graph,root,shown,session,editMovement}){const $=s=>host.querySelector(s),board=$('#nativeStoryBoard'),plane=$('#nativeStoryPlane'),cards=$('#nativeStoryCards'),native=session.reader.byKey(root.mapKey),npcs=session.reader.events(native).npcs,model=sceneMapModel(graph,root,native,npcs),numbers=new Map(model.reachable.map((at,i)=>[at,i+1]));board.classList.add('scene-story');const panel=document.createElement('section');panel.className='scene-map-panel';panel.innerHTML=`<div class="scene-map-toolbar"><b>Event on the map</b><button type="button" id="sceneMapFit">Fit map</button><button type="button" id="sceneMapZoom">Zoom in</button></div><div class="scene-map-scroll"><canvas id="sceneMapCanvas" aria-label="Event actors and movement paths. Select a numbered path to edit it."></canvas></div><p class="scene-map-help">Select a numbered path to edit movement. The event list includes dialogue, battles, conditions, audio, progress and every other decoded command. Branches are alternatives, not simultaneous actions.</p><div id="sceneMapLegend"></div><p id="sceneMapCoverage" class="hint-line"></p>`;plane.insertBefore(panel,cards);const canvas=$('#sceneMapCanvas'),ctx=canvas.getContext('2d');canvas.width=native.layout.width*16;canvas.height=native.layout.height*16;let background=null,zoom=1;const linked=api.project().maps.find(m=>m.rom?.key===root.mapKey&&m.rom?.sourceId===session.id);$('#sceneMapLegend').innerHTML=model.actors.filter(a=>model.routes.some(r=>r.actor===a.id)).map(a=>`<span style="--actor-color:${a.color}">${api.esc(a.label)}</span>`).join('');$('#sceneMapCoverage').textContent=(model.unknownRoutes.length?model.unknownRoutes.length+' movements have a dynamic or unverified position. ':'')+(model.truncated?'Path analysis reached its limit; all commands remain in the event list. ':'')+'Path previews do not simulate collision, timing or native engine code.';
 function paint(){ctx.clearRect(0,0,canvas.width,canvas.height);if(background)ctx.drawImage(background,0,0);ctx.lineWidth=2;ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';for(const a of model.actors){if(!Number.isInteger(a.x)||!Number.isInteger(a.y))continue;ctx.fillStyle=a.color;ctx.strokeStyle='white';ctx.beginPath();ctx.arc((a.x+.5)*16,(a.y+.5)*16,5,0,Math.PI*2);ctx.fill();ctx.stroke();}for(const route of model.routes){if(!route.path.length)continue;ctx.strokeStyle=route.color;ctx.beginPath();route.path.forEach((p,i)=>ctx[i?'lineTo':'moveTo']((p.x+.5)*16,(p.y+.5)*16));ctx.stroke();const end=route.path.at(-1),x=(end.x+.5)*16,y=(end.y+.5)*16;ctx.fillStyle=route.color;ctx.beginPath();ctx.arc(x,y,8,0,Math.PI*2);ctx.fill();ctx.strokeStyle='white';ctx.stroke();ctx.fillStyle='white';ctx.fillText(String(numbers.get(route.at)),x,y);}if(Number.isInteger(model.entry.x)&&Number.isInteger(model.entry.y)){ctx.strokeStyle='#ffe155';ctx.lineWidth=2;ctx.strokeRect(model.entry.x*16,model.entry.y*16,16,16);}}
 const resize=()=>{canvas.style.width=zoom===1?'100%':canvas.width*zoom+'px';canvas.style.maxWidth=zoom===1?'100%':'none';};$('#sceneMapFit').onclick=()=>{zoom=1;resize();};$('#sceneMapZoom').onclick=()=>{zoom=zoom===1?2:Math.min(4,zoom+1);resize();};canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),p={x:(e.clientX-r.left)*canvas.width/r.width/16-.5,y:(e.clientY-r.top)*canvas.height/r.height/16-.5},candidates=model.routes.map(route=>({route,d:Math.min(...route.path.map(q=>Math.hypot(q.x-p.x,q.y-p.y)))})).filter(x=>x.d<1.1).sort((a,b)=>a.d-b.d);if(candidates.length){const route=candidates[0].route;$('#storyStep'+route.at)?.scrollIntoView?.({block:'nearest'});editMovement(route.at);}};
 for(const route of model.routes){const row=$('#storyStep'+route.at);if(!row)continue;row.style.borderLeft='5px solid '+actorColor(route.actor??0);const note=document.createElement('p');note.className='hint-line';note.textContent=(model.actors.find(a=>a.id===route.actor)?.label||'Dynamic actor')+' · '+(route.path.length?'Path '+route.path[0].x+','+route.path[0].y+' → '+route.path.at(-1).x+','+route.path.at(-1).y:'Position determined during play');row.append(note);}
 async function load(){const composed=document.createElement('canvas');composed.width=canvas.width;composed.height=canvas.height;const c=composed.getContext('2d');if(linked&&api.renderStoryMap){const art=await api.renderStoryMap(linked);for(const layer of[art.lower,art.middle,art.upper]){if(!layer)continue;const temporary=document.createElement('canvas');temporary.width=canvas.width;temporary.height=canvas.height;const t=temporary.getContext('2d'),pixels=t.createImageData(canvas.width,canvas.height);pixels.data.set(layer.data??layer.pixels??layer);t.putImageData(pixels,0,0);c.drawImage(temporary,0,0);}}else{const art=session.reader.render(native),pixels=c.createImageData(art.width,art.height);pixels.data.set(art.pixels);c.putImageData(pixels,0,0);}if(!canvas.isConnected)return;background=composed;paint();}resize();paint();load().catch(e=>{if(canvas.isConnected)$('#sceneMapCoverage').textContent='Map artwork could not load: '+e.message;});
 return model;
}
export function mountMovementPathEditor({api,graph,root,session,node,onApply}){const native=session.reader.byKey(root.mapKey),npcs=session.reader.events(native).npcs,model=sceneMapModel(graph,root,native,npcs),route=model.routes.find(r=>r.at===node.at&&r.path.length),start=route?.path[0],host=document.createElement('div');host.className='scene-path-editor';host.innerHTML=`<p>Tap tiles to draw horizontal or vertical segments. Applying replaces this movement sequence, including its waits, facing and effects. The start tile is a preview reference; it does not teleport the actor.</p><div class="scene-map-scroll"><canvas aria-label="Draw movement route"></canvas></div><p class="scene-path-status"></p><div class="smart-actions"><button type="button" data-path-undo>Undo point</button><button type="button" data-path-clear>Clear route</button><button type="button" data-path-apply>Apply drawn route</button></div>`;const canvas=host.querySelector('canvas'),status=host.querySelector('.scene-path-status');canvas.width=native.layout.width*16;canvas.height=native.layout.height*16;canvas.style.width='100%';let points=start?[{...start}]:[],background=null;
 const paint=()=>{const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);if(background)c.drawImage(background,0,0);c.strokeStyle=route?.color||'#2079b0';c.fillStyle=c.strokeStyle;c.lineWidth=3;c.beginPath();points.forEach((p,i)=>c[i?'lineTo':'moveTo']((p.x+.5)*16,(p.y+.5)*16));c.stroke();for(const p of points){c.beginPath();c.arc((p.x+.5)*16,(p.y+.5)*16,3,0,Math.PI*2);c.fill();}status.textContent=points.length?'Start '+points[0].x+','+points[0].y+' · '+(points.length-1)+' drawn segments':'The actor’s position is dynamic. Tap a start reference, then draw its relative route.';};
 canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),point={x:Math.floor((e.clientX-r.left)*canvas.width/r.width/16),y:Math.floor((e.clientY-r.top)*canvas.height/r.height/16)},last=points.at(-1);if(point.x<0||point.y<0||point.x>=native.layout.width||point.y>=native.layout.height)return;if(last&&last.x!==point.x&&last.y!==point.y){status.textContent='Choose a horizontal or vertical segment.';return;}if(last&&last.x===point.x&&last.y===point.y)return;points.push(point);paint();};host.querySelector('[data-path-undo]').onclick=()=>{points.pop();paint();};host.querySelector('[data-path-clear]').onclick=()=>{points=start?[{...start}]:[];paint();};host.querySelector('[data-path-apply]').onclick=()=>{try{if(points.length<2)throw Error('Draw at least one movement segment.');onApply(pathMovement(points).slice(0,-1));}catch(e){status.textContent=e.message;}};
 try{const art=session.reader.render(native),c=document.createElement('canvas');c.width=art.width;c.height=art.height;const x=c.getContext('2d'),d=x.createImageData(art.width,art.height);d.data.set(art.pixels);x.putImageData(d,0,0);background=c;}catch(e){status.textContent=e.message;}paint();return host;}
